-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `PettyCashReconciliation`;
CREATE TABLE `PettyCashReconciliation` (
  `id` VARCHAR(36) NOT NULL,
  `pettyCashAccountId` VARCHAR(36) NOT NULL,
  `reconciliationDate` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `systemBalance` DECIMAL(18,2) NOT NULL,
  `physicalCount` DECIMAL(18,2) NOT NULL,
  `difference` DECIMAL(18,2) NOT NULL,
  `explanation` TEXT NULL,
  `status` VARCHAR(50) NOT NULL DEFAULT 'PENDING_APPROVAL',
  `reconciledById` VARCHAR(36) NOT NULL,
  `approvedById` VARCHAR(36) NULL,
  `approvedAt` DATETIME(3) NULL,
  `journalEntryId` VARCHAR(36) NULL,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `PettyCashReconciliation_journalEntryId_key` (`journalEntryId`),
  KEY `PettyCashReconciliation_pettyCashAccountId_idx` (`pettyCashAccountId`),
  KEY `PettyCashReconciliation_reconciledById_idx` (`reconciledById`),
  KEY `PettyCashReconciliation_approvedById_idx` (`approvedById`),
  KEY `PettyCashReconciliation_reconciliationDate_idx` (`reconciliationDate`),
  CONSTRAINT `PettyCashReconciliation_pettyCashAccountId_fkey` FOREIGN KEY (`pettyCashAccountId`) REFERENCES `Account` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `PettyCashReconciliation_reconciledById_fkey` FOREIGN KEY (`reconciledById`) REFERENCES `User` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `PettyCashReconciliation_approvedById_fkey` FOREIGN KEY (`approvedById`) REFERENCES `User` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 34. Table: FinancialYear
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `FinancialYear`;
CREATE TABLE `FinancialYear` (
  `id` VARCHAR(36) NOT NULL,
  `code` VARCHAR(191) NOT NULL,
  `name` VARCHAR(191) NOT NULL,
  `startDate` DATETIME(3) NOT NULL,
  `endDate` DATETIME(3) NOT NULL,
  `isClosed` TINYINT(1) NOT NULL DEFAULT 0,
  `closedAt` DATETIME(3) NULL,
  `closedById` VARCHAR(36) NULL,
  `reopenedAt` DATETIME(3) NULL,
  `reopenedById` VARCHAR(36) NULL,
  `closingNotes` TEXT NULL,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `FinancialYear_code_key` (`code`),
  KEY `FinancialYear_startDate_endDate_idx` (`startDate`, `endDate`),
  KEY `FinancialYear_isClosed_idx` (`isClosed`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 35. Table: OpeningBalanceBatch
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `OpeningBalanceBatch`;
CREATE TABLE `OpeningBalanceBatch` (
  `id` VARCHAR(36) NOT NULL,
  `openingDate` DATETIME(3) NOT NULL,
  `financialYear` VARCHAR(191) NOT NULL,
  `sourceFinancialYear` VARCHAR(191) NULL,
  `sourceClosingDate` DATETIME(3) NULL,
  `isAutoRolled` TINYINT(1) NOT NULL DEFAULT 0,
  `adjustmentReason` TEXT NULL,
  `adjustedById` VARCHAR(36) NULL,
  `adjustedAt` DATETIME(3) NULL,
  `status` VARCHAR(50) NOT NULL DEFAULT 'Posted',
  `journalEntryId` VARCHAR(36) NOT NULL,
  `createdBy` VARCHAR(191) NOT NULL,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `OpeningBalanceBatch_financialYear_key` (`financialYear`),
  UNIQUE KEY `OpeningBalanceBatch_journalEntryId_key` (`journalEntryId`),
  KEY `OpeningBalanceBatch_openingDate_idx` (`openingDate`),
  CONSTRAINT `OpeningBalanceBatch_journalEntryId_fkey` FOREIGN KEY (`journalEntryId`) REFERENCES `JournalEntry` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 36. Table: OpeningBalanceLine
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `OpeningBalanceLine`;
CREATE TABLE `OpeningBalanceLine` (
  `id` VARCHAR(36) NOT NULL,
  `batchId` VARCHAR(36) NOT NULL,
  `accountId` VARCHAR(36) NOT NULL,
  `glCode` VARCHAR(191) NULL,
  `debitCredit` VARCHAR(10) NOT NULL DEFAULT 'DEBIT',
  `amount` DECIMAL(18,2) NOT NULL,
  `sourceClosingBalance` DECIMAL(18,2) NULL,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `OpeningBalanceLine_batchId_idx` (`batchId`),
  KEY `OpeningBalanceLine_accountId_idx` (`accountId`),
  CONSTRAINT `OpeningBalanceLine_batchId_fkey` FOREIGN KEY (`batchId`) REFERENCES `OpeningBalanceBatch` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `OpeningBalanceLine_accountId_fkey` FOREIGN KEY (`accountId`) REFERENCES `Account` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 37. Table: AuditLog
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `AuditLog`;
CREATE TABLE `AuditLog` (
  `id` VARCHAR(36) NOT NULL,
  `userId` VARCHAR(36) NULL,
  `action` VARCHAR(191) NOT NULL,
  `module` VARCHAR(191) NOT NULL,
  `oldValues` JSON NULL,
  `newValues` JSON NULL,
  `ipAddress` VARCHAR(191) NULL,
  `userAgent` TEXT NULL,
  `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `AuditLog_createdAt_idx` (`createdAt`),
  KEY `AuditLog_userId_idx` (`userId`),
  CONSTRAINT `AuditLog_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

